def analyze(datasets):
    # 库存情况章节：计算预计剩余天数和库存状态
    # 使用 datasets[4] (q4) 期末库存 和 datasets[5] (q5) 销量
    stock_data = {}
    sales_data = {}

    for row in datasets[4]['rows']:
        sku = row['sku']
        stock_data[sku] = {'name': row['product_name'], 'stock': row['stock_on_hand']}

    for row in datasets[5]['rows']:
        sku = row['sku']
        sales_data[sku] = row['units_sold']

    alerts = []
    insights = []

    for sku, info in stock_data.items():
        name = info['name']
        stock = info['stock']
        sold = sales_data.get(sku, 0)

        # 计算日均销量 (假设按月30天估算日均，或直接按总量/30)
        # 题目要求：期末库存除以当期销量再乘30天
        if sold > 0:
            days_left = (stock / sold) * 30
        else:
            days_left = 999 # 无销量则无限

        status = '正常' if days_left > 7 else '预警'
        alerts.append(f'{name}({sku}): 预计可卖 {days_left:.1f} 天 ({status})')
        insights.append(f'{name}({sku}) 当前库存 {stock}')

    return [
        {
            'title': '库存健康度检查',
            'detail': '; '.join(alerts[:2]), # 只展示前两个关键SKU的洞察
            'evidence': {'n': 1}
        },
        {
            'title': '当前库存概览',
            'detail': '重点SKU库存状态已更新。',
            'evidence': {'n': 2}
        }
    ]

